import{_ as p,a0 as i,w as r,s as a,ao as l,I as o,x as e,a1 as u,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧——截屏 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——截屏 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——截屏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——截屏 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Take Screenshots Of your Desktop","title":"每日Ubuntu小技巧——截屏","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Take Screenshots Of your Desktop.md","filePath":"[post].md"}'),d={name:"201402/Daily Ubuntu Tips – Take Screenshots Of your Desktop.md"};function b(T,t,f,m,k,g){const n=i("Link");return r(),a("div",null,[t[11]||(t[11]=l('<h1 id="每日ubuntu小技巧——截屏" tabindex="-1">每日Ubuntu小技巧——截屏 <a class="header-anchor" href="#每日ubuntu小技巧——截屏" aria-label="Permalink to “每日Ubuntu小技巧——截屏”">​</a></h1><p>Ubuntu 是一個功能強大的現代化操作系統，支持你進行多種任務。從使用 Libreoffice 創建和編輯文檔到使用 GIMP 處理圖片，Ubuntu 都是最佳選擇。</p><p>如果你需要一個功能強大的操作系統來完成工作，那麼你一定會考慮選擇 Ubuntu。</p><p>你可以用 Ubuntu 來完成的另一件事情是為你的桌面截屏或者激活應用程序的窗口。你可以安裝很多第三方工具來完成這些事情，但是實際沒有必要，因為 Ubuntu 安裝時已自帶這些功能。</p><p>如果你想向別人展示如何在Ubuntu上面做一些事情，那麼這個應用程序就非常有用。截屏得到的圖片文件可以保存，也可以通過email發送給其他人。</p><p>使用截屏程序，需要進入到面板界面或者直接按下鍵盤上面的 Windows 鍵進入面板，Windows 鍵指的是鍵盤空格鍵的左邊有 Windows 圖標的鍵。</p><p>當面板打開後，找到“截屏”，然後打開這個程序(譯者注：需要在已安裝程序中查找或者直接在搜索框中輸入“截圖”)。</p><p>以下是你能夠通過這個截屏程序做的操作：</p><ul><li>截取整個屏幕</li><li>截取當前程序窗口</li><li>截取特定區域</li></ul><p>如果你想在截圖時將鼠標箭頭一起截取，可以將在下方圖片 Effects 選項中的&quot;Include pointer&quot;選項選中即可。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/screenshot.png" alt=""></p><p>當你選擇好你的截屏方式後，點擊圖片中的‘<strong>截圖</strong>’按鈕，然後程序就會退出並且自動保存圖片。</p><p>如果你想截取特定區域，需要選擇該方式，當你點擊‘<strong>截圖</strong>’按鈕時，鼠標會變成十字形狀。此刻，你可以拖拽這個十字形狀的鼠標，來得到任意你想截取的區域。在你停止拖拽鼠標後，圖片會自動截取。</p><p>以上就是你在使用 Ubuntu 時，如何完成一個截圖的操作。</p><p>希望能夠幫助到你，歡迎再來。</p><p>享受截屏的歡樂！</p><hr>',17)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-take-screenshots-of-your-desktop/"},{default:s(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-take-screenshots-of-your-desktop/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=e("譯者：",-1)),u(n,{href:"https://github.com/liuaiping"},{default:s(()=>[...t[2]||(t[2]=[e("liuaiping",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),u(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),u(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const _=p(d,[["render",b]]);export{w as __pageData,_ as default};
